  VALUES ("domaine-eden", "Le Domaine Éden Assinie", "Domaine grandiose pour réceptions, mariages, séminaires & grands groupes", "evenement", "Événements & Séminaires", "Assinie-Mafia, Km 18", "Le Domaine Éden est une propriété de prestige sans équivalent à Assinie, s'étendant sur plus de 2 500 m² de terrain paysager. Conçu spécialement pour recevoir avec faste, il abrite une piscine monumentale avec bar aquatique immergé, un préau de réception couvert pour 80 convives, une cuisine de traiteur professionnelle et 7 suites haut de gamme. C'est l'adresse de référence pour les retraites d'entreprise, les mariages intimes et les grands anniversaires.", 500000, 762, 920000, 18, 7, 8, "7 grandes suites avec salles de bain privatives", "disponible", "Grands Groupes", 1, 1, 4.98, 19, "[\"https://images.unsplash.com/photo-1564013799919-ab600027ffc6?auto=format&fit=crop&w=1200&q=80\",\"https://images.unsplash.com/photo-1576013551627-0cc20b96c2a7?auto=format&fit=crop&w=1200&q=80\",\"https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=1200&q=80\",\"https://images.unsplash.com/photo-1513694203232-719a280e022f?auto=format&fit=crop&w=1200&q=80\"]", "[\"Piscine XXL avec bar aquatique\",\"Parc paysager pour réceptions (jusqu'à 80 pers.)\",\"7 suites indépendantes climatisées\",\"Espace séminaire avec projecteur & sono\",\"Cuisine professionnelle traiteur\",\"Grand ponton privé sur la lagune\",\"Chef et maître d'hôtel disponibles\",\"Sécurité renforcée 24/7 avec vidéosurveillance\",\"Groupe électrogène industriel insonorisé\",\"Wi-Fi ultra-puissant sur tout le domaine\",\"Grand parking pour plus de 10 véhicules\"]", "[\"Capacité 18 couchages\",\"Jusqu'à 80 invités cocktail\",\"Bar aquatique\",\"Prestations traiteur VIP\"]", 3)
  ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `tagline`=VALUES(`tagline`), `category`=VALUES(`category`), `category_label`=VALUES(`category_label`), `location`=VALUES(`location`), `description`=VALUES(`description`), `price_per_night`=VALUES(`price_per_night`), `price_euro`=VALUES(`price_euro`), `weekend_package`=VALUES(`weekend_package`), `capacity`=VALUES(`capacity`), `bedrooms`=VALUES(`bedrooms`), `bathrooms`=VALUES(`bathrooms`), `beds`=VALUES(`beds`), `status`=VALUES(`status`), `badge`=VALUES(`badge`), `visible`=VALUES(`visible`), `featured`=VALUES(`featured`), `rating`=VALUES(`rating`), `reviews_count`=VALUES(`reviews_count`), `images`=VALUES(`images`), `features`=VALUES(`features`), `highlights`=VALUES(`highlights`), `sort_order`=VALUES(`sort_order`);
