  VALUES ("pavillon-serenite", "Pavillon Sérénité - Duplex Privé", "Nid douillet intime pour couples et escapades romantiques", "romantique", "Escapade Romantique", "Assinie, Km 6", "Le Pavillon Sérénité est un charmant duplex architectural parfait pour un week-end romantique en tête-à-tête ou pour deux couples d'amis. Profitez d'une atmosphère lounge paisible, de chambres douillettes avec balcons fleuris, d'un bassin d'eau rafraîchissant privatif et d'un hamac sous les cocotiers pour vous ressourcer loin de l'effervescence d'Abidjan.", 120000, 183, 220000, 4, 2, 2, "2 lits Queen Size climatisés", "disponible", "Spécial Couple", 1, 0, 4.92, 33, "[\"https://images.unsplash.com/photo-1600585152220-90363fe7e115?auto=format&fit=crop&w=1200&q=80\",\"https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?auto=format&fit=crop&w=1200&q=80\",\"https://images.unsplash.com/photo-1618773928121-c32242e63f39?auto=format&fit=crop&w=1200&q=80\"]", "[\"Bassin privé rafraîchissant / Jacuzzi extérieur\",\"2 chambres cosy à l'étage climatisées\",\"Balcon avec vue sur le coucher de soleil\",\"Cuisine équipée & machine Nespresso\",\"Salon intime avec Smart TV\",\"Wi-Fi rapide\",\"Hamac et coin lecture détente\",\"Service petit-déjeuner sur demande\",\"Gardiennage discret 24/7\"]", "[\"Ambiance intimiste\",\"Parfait pour couples\",\"Calme absolu\"]", 4)
  ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `tagline`=VALUES(`tagline`), `category`=VALUES(`category`), `category_label`=VALUES(`category_label`), `location`=VALUES(`location`), `description`=VALUES(`description`), `price_per_night`=VALUES(`price_per_night`), `price_euro`=VALUES(`price_euro`), `weekend_package`=VALUES(`weekend_package`), `capacity`=VALUES(`capacity`), `bedrooms`=VALUES(`bedrooms`), `bathrooms`=VALUES(`bathrooms`), `beds`=VALUES(`beds`), `status`=VALUES(`status`), `badge`=VALUES(`badge`), `visible`=VALUES(`visible`), `featured`=VALUES(`featured`), `rating`=VALUES(`rating`), `reviews_count`=VALUES(`reviews_count`), `images`=VALUES(`images`), `features`=VALUES(`features`), `highlights`=VALUES(`highlights`), `sort_order`=VALUES(`sort_order`);
