INSERT INTO `activities` (`id`, `title`, `subtitle`, `description`, `image`, `images`, `duration`, `price`, `badge`, `visible`, `featured`, `sort_order`)
  VALUES ("balade-bateau", "Balade privée en Bateau vers La Passe", "L'incontournable d'Assinie", "Embarquez depuis le ponton de votre villa pour une navigation le long de la lagune jusqu'à la mythique Passe d'Assinie, où les eaux calmes de la lagune Aby rencontrent la houle de l'océan Atlantique. Arrêt sur les bancs de sable préservés.", "assets/images/bateau-excursion-lagune.jpg", "[\"assets/images/bateau-excursion-lagune.jpg\"]", "2 heures ou demi-journée", "À partir de 60 000 FCFA / sortie", "Top Activité", 1, 0, 0)
