-- 3 ligne(s) dans `reviews`
INSERT INTO `reviews` (`id`, `author`, `city`, `stay`, `rating`, `date_label`, `comment`, `avatar`, `visible`, `sort_order`)
  VALUES ("avis-1", "Marc & Diane K.", "Abidjan, Cocody", "Séjour en famille à la Villa L'Oasis", 5, "Il y a 2 semaines", "Nous avons passé un week-end tout simplement magique ! La villa est encore plus belle en vrai que sur les photos de la page Facebook. Le ponton privé nous a permis d'embarquer directement en bateau pour La Passe. Le personnel était aux petits soins et la piscine était d'une propreté irréprochable. Nous reviendrons sans hésiter !", "https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=150&q=80", 1, 0)
  ON DUPLICATE KEY UPDATE `author`=VALUES(`author`), `city`=VALUES(`city`), `stay`=VALUES(`stay`), `rating`=VALUES(`rating`), `date_label`=VALUES(`date_label`), `comment`=VALUES(`comment`), `avatar`=VALUES(`avatar`), `visible`=VALUES(`visible`), `sort_order`=VALUES(`sort_order`);
INSERT INTO `reviews` (`id`, `author`, `city`, `stay`, `rating`, `date_label`, `comment`, `avatar`, `visible`, `sort_order`)
  VALUES ("avis-2", "Christelle B.", "Abidjan, Plateau", "Anniversaire au Domaine Éden", 5, "Il y a 1 mois", "J'ai fêté mes 30 ans avec 35 amis au Domaine Éden. Organisation parfaite via WhatsApp avec l'équipe de Détente et Loisirs. Le bar aquatique dans la piscine a fait l'unanimité. Merci pour le professionnalisme et la réactivité du service client !", "https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=150&q=80", 1, 1)
  ON DUPLICATE KEY UPDATE `author`=VALUES(`author`), `city`=VALUES(`city`), `stay`=VALUES(`stay`), `rating`=VALUES(`rating`), `date_label`=VALUES(`date_label`), `comment`=VALUES(`comment`), `avatar`=VALUES(`avatar`), `visible`=VALUES(`visible`), `sort_order`=VALUES(`sort_order`);
INSERT INTO `reviews` (`id`, `author`, `city`, `stay`, `rating`, `date_label`, `comment`, `avatar`, `visible`, `sort_order`)
  VALUES ("avis-3", "Patrick & Sandra V.", "Expatriés français résidents en Côte d'Ivoire", "Séjour à la Résidence Palm Beach", 5, "Il y a 3 semaines", "Le luxe d'être les pieds dans l'eau côté océan sans aucun vis-à-vis. Les enfants ont adoré la plage et la piscine privée, et le groupe électrogène a assuré une électricité sans coupure tout le week-end avec la clim au frais. Recommandé à 100%.", "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=150&q=80", 1, 2)
  ON DUPLICATE KEY UPDATE `author`=VALUES(`author`), `city`=VALUES(`city`), `stay`=VALUES(`stay`), `rating`=VALUES(`rating`), `date_label`=VALUES(`date_label`), `comment`=VALUES(`comment`), `avatar`=VALUES(`avatar`), `visible`=VALUES(`visible`), `sort_order`=VALUES(`sort_order`);

